import { LOCATIONS, CATEGORIES, uid, policyFor, publicReport, matchScore, analytics, duplicateCandidates, isOpen } from './domain.js';
import { getAll, put, remove, clearAll, exportData, importData } from './store.js';

const app=document.querySelector('#app'), modal=document.querySelector('#modal'), toastEl=document.querySelector('#toast');
const NAV=[['home','⌂','Home'],['map','⌖','Campus map'],['find','⌕','Find items'],['report','＋','Report an item'],['recovery','↗','Recovery centre'],['insights','▥','Insights & trends'],['activity','◷','My activity'],['admin','⚙','Admin / staff']];
const state={page:'home',role:localStorage.getItem('cfi-role')||'student',kind:'lost',data:{reports:[],claims:[],custody:[],notifications:[],audit:[]},mapMode:'items',mapLayer:'all',mapCategory:'all',mapStatus:'all',mapSince:null,mapQuery:'',mapSelected:null,zoom:1,panX:0,panY:0,selectedReport:null,filters:{kind:'all',category:'all',location:'all',status:'all',query:''}};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const loc=id=>LOCATIONS.find(x=>x.id===id);
const dateLabel=d=>d?new Date(`${d}T00:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'Date not set';
const ago=d=>{const n=Math.floor((Date.now()-new Date(d))/86400000);return n<=0?'Today':n===1?'Yesterday':`${n} days ago`;};
const statusClass=s=>String(s||'').toLowerCase().replace(/[^a-z]+/g,'-');
const now=()=>new Date().toISOString();
function toast(s){toastEl.textContent=s;toastEl.classList.add('show');setTimeout(()=>toastEl.classList.remove('show'),2800);}
async function refresh(){for(const k of Object.keys(state.data))state.data[k]=await getAll(k);render();}
async function audit(action,targetId,details=''){const event={id:uid('audit'),action,targetId,details,actor:state.role,createdAt:now()};await put('audit',event);state.data.audit.push(event);}
async function notify(message,reportId=null){const n={id:uid('notice'),message,reportId,read:false,createdAt:now()};await put('notifications',n);state.data.notifications.push(n);}
async function saveReport(r){await put('reports',r);await audit('Report created',r.id,`${r.kind} report`);if(r.kind==='found')await notify('A found-item report is waiting for staff review.',r.id);else{
  const candidates=state.data.reports.filter(f=>f.kind==='found').map(f=>({r:f,...matchScore(r,f)})).filter(x=>x.score>=45);
  if(candidates.length)await notify(`${candidates.length} possible match${candidates.length===1?'':'es'} found for ${r.id}.`,r.id);
}}
function go(page){state.page=page;state.selectedReport=null;history.replaceState(null,'',`#${page}`);render();}
function icon(i){return `<span class="nav-icon" aria-hidden="true">${i}</span>`;}
function layout(content){const unread=state.data.notifications.filter(n=>!n.read).length;return `<div class="app-shell"><aside class="sidebar"><a class="brand" href="#home" data-page="home"><span class="brand-mark">F</span><span>Campus <b>FindIt</b><small>Lost. Found. Reunited.</small></span></a><div class="nav-label">WORKSPACE</div><nav>${NAV.map(([id,ic,label])=>`<button class="nav-item ${state.page===id?'active':''}" data-page="${id}">${icon(ic)}<span>${label}</span>${id==='activity'&&unread?`<i class="nav-badge">${unread}</i>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="demo-note"><span class="pulse-dot"></span><div><b>Local demo</b><small>Saved on this device</small></div></div><button class="role-switch" id="role-switch"><span class="avatar">${state.role==='staff'?'S':'M'}</span><span><b>${state.role==='staff'?'Demo staff':'Demo student'}</b><small>Switch demo role</small></span><span class="chevron">⌄</span></button></div></aside><main class="main-area"><header class="topbar"><div class="mobile-brand"><span class="brand-mark">F</span> Campus FindIt</div><div class="breadcrumb">Campus community <span>/</span> <b>${NAV.find(x=>x[0]===state.page)?.[2]||'Home'}</b></div><div class="top-actions"><button class="icon-button" id="bell" aria-label="Notifications">♧${unread?'<i></i>':''}</button><button class="top-avatar" id="role-switch-top" aria-label="Switch demo role" title="Switch demo role">${state.role==='staff'?'S':'M'}</button></div></header><div class="page-wrap">${content}</div><footer>Campus FindIt <span>•</span> Illustrative campus · Your records stay in this browser</footer></main><nav class="mobile-nav">${NAV.map(([id,ic,label])=>`<button class="${state.page===id?'active':''}" data-page="${id}">${icon(ic)}<small>${({home:'Home',map:'Map',find:'Find',report:'Report',recovery:'Recovery',insights:'Insights',activity:'Activity',admin:'Staff'})[id]}</small></button>`).join('')}</nav></div>`;}
function pageTitle(kicker,title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`;}
function empty(iconText,title,body,action=''){return `<div class="empty-state"><div class="empty-icon">${iconText}</div><h3>${title}</h3><p>${body}</p>${action}</div>`;}
function button(text,cls='btn-primary',attrs=''){return `<button class="${cls}" ${attrs}>${text}</button>`;}
function statusPill(s){return `<span class="status-pill ${statusClass(s)}">${esc(s||'Open')}</span>`;}
function cardReport(r,compact=false){const p=publicReport(r);if(!p)return '';const place=p.locationName||loc(p.locationId)?.name||'Campus';return `<article class="report-card ${compact?'compact':''}" data-open-report="${esc(r.id)}"><div class="report-thumb ${p.kind}">${p.image?`<img src="${p.image}" alt="Approved item photo">`:`<span>${p.kind==='lost'?'⌕':'＋'}</span>`}</div><div class="report-info"><div class="report-topline"><span class="kind-tag ${p.kind}">${p.kind==='lost'?'LOST':'FOUND'}</span>${statusPill(p.status)}</div><h3>${esc(p.itemType||p.category)}</h3><p>${esc(p.description||p.category)}</p><div class="report-meta"><span>⌖ ${esc(place)}</span><span>· ${dateLabel(p.date)}</span></div></div><span class="card-arrow">↗</span></article>`;}
function statCard(label,val,note,iconText){return `<div class="stat-card"><div class="stat-icon">${iconText}</div><div><span>${label}</span><strong>${val}</strong><small>${note}</small></div></div>`;}
function homePage(){const reports=state.data.reports.filter(r=>r.kind==='lost'||(r.kind==='found'&&r.approved)).filter(r=>isOpen(r)).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));const mine=state.data.reports.filter(r=>r.owner==='demo');const matches=mine.filter(r=>r.kind==='lost').flatMap(l=>state.data.reports.filter(f=>f.kind==='found'&&f.approved).map(f=>({f,...matchScore(l,f),l}))).filter(m=>m.score>=45).sort((a,b)=>b.score-a.score).slice(0,2);const stats=analytics(state.data.reports,state.data.claims);const hour=new Date().getHours();const greeting=hour<12?'Good morning':hour<18?'Good afternoon':'Good evening';return `${pageTitle('YOUR CAMPUS, RECONNECTED',greeting,'A simpler way to find what matters and return what belongs.',button('＋ Report an item','btn-primary','data-page="report"'))}<section class="hero-card"><div class="hero-copy"><span class="hero-kicker">LOST SOMETHING? FOUND SOMETHING?</span><h2>Small things find<br><em>their way home.</em></h2><p>Search campus reports, share a useful clue, and coordinate a safe handover.</p><div class="hero-actions">${button('I lost something','btn-light','data-report-kind="lost"')} ${button('I found something','btn-outline-light','data-report-kind="found"')}</div></div><div class="hero-art"><div class="art-circle"></div><div class="art-pin">⌖</div><span class="art-line"></span><div class="art-chip">Made for campus</div></div></section><div class="quick-grid"><button class="quick-card" data-page="find"><span class="quick-icon lilac">⌕</span><b>Search items</b><small>Browse approved reports</small><span class="quick-arrow">↗</span></button><button class="quick-card" data-page="map"><span class="quick-icon mint">⌖</span><b>Explore campus</b><small>See landmarks and reports</small><span class="quick-arrow">↗</span></button><button class="quick-card" data-page="recovery"><span class="quick-icon peach">↗</span><b>Recovery centre</b><small>Follow a claim to handover</small><span class="quick-arrow">↗</span></button></div><div class="section-head"><div><div class="eyebrow">CAMPUS BOARD</div><h2>Recently reported</h2></div><button class="text-button" data-page="find">View all reports <span>→</span></button></div>${reports.length?`<div class="report-list">${reports.slice(0,3).map(r=>cardReport(r)).join('')}</div>`:empty('⌕','It starts with a report','There are no item reports yet. Add a report and it will appear here after the relevant review.')}${matches.length?`<div class="section-head"><div><div class="eyebrow">A POSSIBLE LEAD</div><h2>Matches to check</h2></div><button class="text-button" data-page="activity">My activity →</button></div><div class="match-strip">${matches.map(m=>`<div class="match-card"><div class="match-score">${m.score}<small>pts</small></div><div><b>${esc(m.f.itemType||m.f.category)} could match your ${esc(m.l.itemType||m.l.category)}</b><small>${esc(m.f.locationName||loc(m.f.locationId)?.name)} · ${m.factors.join(' · ')}</small></div><button class="btn-quiet" data-open-report="${m.f.id}">Review →</button></div>`).join('')}</div>`:''}<div class="home-bottom"><div class="panel insight-mini"><div><div class="eyebrow">LIVE CAMPUS SNAPSHOT</div><h3>Patterns from real reports</h3><p>${stats.lost+stats.found?`${stats.lost} lost and ${stats.found} found reports so far.`:'Insights will appear when reports are submitted.'}</p></div><div class="mini-number">${stats.recoveryRate}<small>% recovered</small></div><button class="text-button" data-page="insights">Explore insights →</button></div><div class="privacy-tip"><span>✳</span><div><b>Keep one clue private</b><p>Leave a distinctive mark or detail out of public descriptions. It helps confirm ownership later.</p></div></div></div>`;}
function selector(name,items,value,allLabel='All'){return `<select name="${name}"><option value="all">${allLabel}</option>${items.map(x=>typeof x==='string'?`<option value="${esc(x)}" ${value===x?'selected':''}>${esc(x)}</option>`:`<option value="${x.id}" ${value===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`;}
function findPage(){const f=state.filters;let list=state.data.reports.filter(r=>publicReport(r));if(f.kind!=='all')list=list.filter(r=>r.kind===f.kind);if(f.category!=='all')list=list.filter(r=>r.category===f.category);if(f.location!=='all')list=list.filter(r=>r.locationId===f.location);if(f.status!=='all')list=list.filter(r=>r.status===f.status);if(f.query){const q=f.query.toLowerCase();list=list.filter(r=>{const p=publicReport(r);return `${p.itemType} ${p.category} ${p.description} ${p.locationName}`.toLowerCase().includes(q);});}list.sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return `${pageTitle('DISCOVER','Find an item','Search approved lost and found reports across your campus.') }<section class="panel filters-panel"><label class="search-box"><span>⌕</span><input id="search-query" placeholder="Search item, colour, or landmark..." value="${esc(f.query)}"></label><div class="filter-row"><label>Report type${selector('kind',['lost','found'],f.kind,'All types')}</label><label>Category${selector('category',CATEGORIES,f.category,'All categories')}</label><label>Location${selector('location',LOCATIONS,f.location,'All locations')}</label><label>Status${selector('status',['under review','active','open','recovered'],f.status,'All statuses')}</label><button class="text-button" id="clear-filters">Clear filters</button></div></section><div class="results-line"><b>${list.length} ${list.length===1?'result':'results'}</b><span>Newest first · private details are hidden</span></div>${list.length?`<div class="report-list">${list.map(r=>cardReport(r)).join('')}</div>`:empty('⌕',f.query||f.kind!=='all'?'No matching reports':'No approved reports yet','Try a different search or check back after a new report is reviewed.',button('Report an item','btn-secondary','data-page="report"'))}`;}
function reportPage(){return `${pageTitle('ADD TO THE CAMPUS BOARD','Report an item','A few details can help reunite an item with its owner. Keep one identifying clue private.')}<div class="form-layout"><div class="form-main panel"><div class="segmented"><button class="${state.kind==='lost'?'active':''}" data-report-kind="lost">⌕ &nbsp;I lost something</button><button class="${state.kind==='found'?'active':''}" data-report-kind="found">＋ &nbsp;I found something</button></div><form id="report-form"><input type="hidden" name="kind" value="${state.kind}"><div class="form-section"><h3>About the item</h3><div class="form-grid"><label>Category <span>*</span><select name="category" required>${CATEGORIES.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Item type <span>*</span><input name="itemType" required maxlength="80" placeholder="e.g. Blue notebook"></label><label>Brand or model <small>optional</small><input name="brand" maxlength="80" placeholder="If known"></label><label>Colour <small>optional</small><input name="color" maxlength="40" placeholder="e.g. Navy blue"></label><label>Date ${state.kind==='lost'?'last seen':'found'} <span>*</span><input type="date" name="date" max="${new Date().toISOString().slice(0,10)}" required value="${new Date().toISOString().slice(0,10)}"></label><label>Approximate time <small>optional</small><input type="time" name="time"></label></div><label>Description <span>*</span><textarea name="description" required maxlength="300" rows="3" placeholder="Describe the item without giving away your private clue."></textarea></label>${state.kind==='found'?`<div class="form-grid"><label>Value classification<select name="value"><option>Less expensive</option><option>Expensive</option></select></label><label>How is it being handled?<select name="handling"><option>With me for now</option><option>Handed to campus staff</option><option>At the security desk</option></select></label></div>`:`<label>Private distinguishing detail <small>only used during verification</small><textarea name="privateClue" rows="2" maxlength="300" placeholder="A mark, sticker, contents, or other detail only the owner knows"></textarea></label>`}</div><div class="form-section"><h3>Where on campus?</h3><div class="form-grid"><label>Landmark <span>*</span><select name="locationId" required>${LOCATIONS.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}</select></label><label>Additional location details <small>optional · kept private</small><input name="locationDetail" maxlength="120" placeholder="Broad area only"></label></div><button type="button" class="text-button" data-page="map">⌖ Choose from campus map</button></div><div class="form-section"><h3>Add a photo <small>optional</small></h3><label class="upload-box"><input type="file" name="image" accept="image/jpeg,image/png,image/webp" hidden><span class="upload-icon">＋</span><span><b>Choose a photo</b><small>JPG, PNG or WebP · max 3 MB</small></span></label><small class="form-help">Avoid uploading IDs or images that reveal private personal information.</small></div><div class="privacy-callout"><span>◈</span><div><b>${state.kind==='found'?'Staff review before publishing':'Your private clue stays restricted'}</b><p>${state.kind==='found'?'Found reports are reviewed before they appear publicly. Valuable or sensitive items go through additional staff review.':'Your identifying clue will not appear in public search or on the map.'}</p></div></div><div class="form-actions"><button class="btn-primary" type="submit">Submit ${state.kind} report <span>→</span></button><span class="form-footnote">Saved on this device in this browser</span></div></form></div><aside class="form-side"><div class="side-card"><div class="side-step">01</div><h3>Share the useful parts</h3><p>Item type, colour, and a broad landmark help people spot a possible match.</p></div><div class="side-card"><div class="side-step">02</div><h3>Keep a clue back</h3><p>Don't share unique marks or contents in the public description. Use them to verify a claim.</p></div><div class="side-card"><div class="side-step">03</div><h3>Meet safely</h3><p>Valuable items are routed through the demo staff workflow and in-person handover.</p></div><div class="local-data"><b>Local prototype</b><p>Records stay in this browser profile. They are not shared across devices or students.</p></div></aside></div>`;}
function mapPage(){const q=state.mapQuery.toLowerCase();const landmarks=LOCATIONS.filter(l=>l.name.toLowerCase().includes(q)||l.type.toLowerCase().includes(q));const mode=state.mapMode;const cutoff=state.mapSince||state.hotspotSince;const filtered=state.data.reports.filter(r=>publicReport(r)).filter(r=>!cutoff||new Date(r.createdAt)>=new Date(cutoff)).filter(r=>(state.mapLayer==='all'||r.kind===state.mapLayer)&&(state.mapCategory==='all'||r.category===state.mapCategory)&&(state.mapStatus==='all'||r.status===state.mapStatus));const stats=analytics(filtered,state.data.claims);const selected=state.mapSelected?loc(state.mapSelected):null;const tops=stats.byLocation;const markers=filtered;return `${pageTitle('LOCATION INTELLIGENCE','Campus map','An illustrative campus layout. Locations are broad areas, not exact storage points.',button('Reset view','btn-secondary','id="map-reset"'))}<div class="map-tabs"><button class="${mode==='items'?'active':''}" data-map-mode="items">Reported items</button><button class="${mode==='hotspots'?'active':''}" data-map-mode="hotspots">Loss hotspots</button><button class="${mode==='ranked'?'active':''}" data-map-mode="ranked">Frequent locations</button><button class="${mode==='explorer'?'active':''}" data-map-mode="explorer">Location explorer</button></div><div class="map-layout"><section class="panel map-panel"><div class="map-toolbar"><label class="search-box"><span>⌕</span><input id="map-search" value="${esc(state.mapQuery)}" placeholder="Find a campus landmark"></label><div class="map-controls"><button id="zoom-out" aria-label="Zoom out">−</button><span>${Math.round(state.zoom*100)}%</span><button id="zoom-in" aria-label="Zoom in">＋</button></div></div><div class="map-viewport"><svg id="campus-map" viewBox="0 0 100 100" role="img" aria-label="Illustrative campus map. Use the location list to select a landmark."><rect width="100" height="100" fill="#f5f7f2"/><path class="map-road" d="M2 49 H98 M22 8 V92 M6 30 H93 M12 72 H88 M32 8 V88 M54 8 V90 M76 8 V91"/><path class="map-path" d="M10 50 L33 20 L51 18 L68 28 L77 62 L73 82 M33 20 L46 58 L60 62 L56 43 L30 43 L20 71 L40 80"/>${LOCATIONS.map(l=>`<g class="map-landmark ${selected?.id===l.id?'selected':''}" data-map-location="${l.id}" transform="translate(${l.x},${l.y})"><circle r="5.3"/><text text-anchor="middle" y="1.1">${esc(l.name.split(' ').map(w=>w[0]).join('').slice(0,2))}</text><text class="map-label" text-anchor="middle" y="9">${esc(l.name)}</text></g>`).join('')}${mode==='items'?markers.map(r=>{const l=loc(r.locationId);return l?`<g class="report-marker ${r.kind}" data-open-report="${r.id}" transform="translate(${l.x+2},${l.y-3})"><circle r="2.8"/><text text-anchor="middle" y="1.2">${r.kind==='lost'?'?':'+'}</text></g>`:''}).join(''):''}${mode==='hotspots'?tops.map((x,i)=>`<circle class="hotspot" cx="${x.location.x}" cy="${x.location.y}" r="${Math.min(10,3+x.count)}" opacity="${.22+Math.min(.45,x.count*.08)}"/>`).join(''):''}</svg></div><div class="map-legend"><span><i class="legend-dot lost"></i> Lost</span><span><i class="legend-dot found"></i> Found</span><span><i class="legend-dot landmark"></i> Landmark</span><span class="map-caption">Illustrative layout · not to scale</span></div><div class="map-layer"><span>Report layer</span>${['all','lost','found'].map(x=>`<button class="${state.mapLayer===x?'active':''}" data-map-layer="${x}">${x==='all'?'All':x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><div class="map-extra-filters"><label>Category${selector('category',CATEGORIES,state.mapCategory,'All categories')}</label><label>Status${selector('status',['open','active','under review','recovered'],state.mapStatus,'All statuses')}</label><label>From date<input id="map-date-from" type="date" value="${esc(state.mapSince||'')}"></label></div></section><aside class="panel location-panel"><div class="panel-heading"><div><div class="eyebrow">${mode==='hotspots'?'CALCULATED FROM REPORTS':mode==='ranked'?'LOCATION RANKING':'LANDMARK DIRECTORY'}</div><h3>${selected?esc(selected.name):mode==='hotspots'?'Reporting hotspots':mode==='ranked'?'Frequent locations':'Campus landmarks'}</h3></div>${selected?`<button class="icon-button" id="clear-location" aria-label="Clear selected location">×</button>`:''}</div>${selected?`<div class="location-detail"><span class="location-type">${esc(selected.type)}</span><p>Reports at this landmark: <b>${tops.find(x=>x.location.id===selected.id)?.count||0}</b></p><div class="location-actions"><button class="btn-secondary" data-map-report="${selected.id}">Use in a report</button><button class="text-button" data-filter-location="${selected.id}">View reports →</button></div></div>`:''}${mode==='hotspots'?`<div class="map-filters"><label>Date range<select id="hotspot-range"><option value="all">All time</option><option value="7">Last 7 days</option><option value="30">Last 30 days</option></select></label><label>Minimum reports<select id="hotspot-min"><option>1</option><option>2</option><option>3</option></select></label></div>${tops.filter(x=>x.count>=Number(document.querySelector('#hotspot-min')?.value||1)).length?tops.map(x=>`<button class="rank-row" data-map-location="${x.location.id}"><span class="rank-num">${x.count}</span><span><b>${esc(x.location.name)}</b><small>${x.lost} lost · ${x.found} found · ${x.recovered} recovered</small></span><i class="rank-bar" style="--bar:${Math.max(8,x.count/(tops[0]?.count||1)*100)}%"></i></button>`).join(''):empty('⌖','No hotspots yet','Hotspots are calculated from actual reports.')}<p class="privacy-note">High counts describe reporting patterns only; they do not indicate risk.</p>`:mode==='ranked'?tops.length?tops.map((x,i)=>`<button class="rank-row" data-map-location="${x.location.id}"><span class="rank-position">${String(i+1).padStart(2,'0')}</span><span><b>${esc(x.location.name)}</b><small>${x.count} report${x.count===1?'':'s'} · ${x.lost} lost / ${x.found} found · ${x.recovered} recovered</small></span><span class="row-arrow">→</span></button>`).join(''):empty('⌖','No reported locations yet','When reports are submitted, this list will rank the locations.'):`<div class="landmark-list">${landmarks.map(l=>`<button class="landmark-row ${selected?.id===l.id?'selected':''}" data-map-location="${l.id}"><span class="landmark-symbol">⌖</span><span><b>${esc(l.name)}</b><small>${esc(l.type)}</small></span><span class="row-arrow">→</span></button>`).join('')||'<p class="muted">No landmarks match that search.</p>'}</div>`}</aside></div>`;}
function claimsFor(reportId){return state.data.claims.filter(c=>c.reportId===reportId);}
function recoveryPage(){const pending=state.data.reports.filter(r=>r.kind==='found'&&r.status!=='recovered'&&r.status!=='withdrawn');const claims=state.data.claims;const custody=state.data.custody;return `${pageTitle('SAFE HANDOVER','Recovery centre','Follow found items and ownership claims through review, custody, and in-person handover.',state.role==='staff'?button('Review queue','btn-secondary','data-page="admin"'): '')}<div class="recovery-stats">${statCard('Awaiting review',pending.filter(r=>!r.approved).length,'Found item reports','◷')}${statCard('Open claims',claims.filter(c=>!['Rejected','Recovered'].includes(c.status)).length,'Across found reports','◇')}${statCard('In custody',custody.filter(c=>c.status!=='released').length,'Official handovers','▣')}</div><div class="section-head"><div><div class="eyebrow">ACTIVE CASES</div><h2>Items and claims</h2></div><span class="local-chip">DEMO WORKFLOW</span></div>${claims.length?`<div class="case-list">${claims.map(c=>{const r=state.data.reports.find(x=>x.id===c.reportId);return `<article class="case-card"><div class="case-id">${esc(c.id.slice(-8).toUpperCase())}</div><div class="case-main"><div class="case-title"><b>${esc(r?.itemType||'Missing report')}</b>${statusPill(c.status)}</div><p>Claim for <b>${esc(c.reportId)}</b> · submitted ${ago(c.createdAt)}</p>${c.owner==='demo'?`<small>Your explanation: ${esc(c.explanation)}</small>`:''}</div>${r?button('Open case','btn-secondary',`data-open-report="${r.id}"`):''}</article>`;}).join('')}</div>`:empty('↗','No active recovery cases','Ownership claims and confirmed handovers will appear here.')}${pending.length?`<div class="section-head"><div><div class="eyebrow">FOUND ON CAMPUS</div><h2>Found reports</h2></div></div><div class="report-list">${pending.map(cardReport).join('')}</div>`:''}<div class="workflow-note"><b>Physical recovery always requires a handover record.</b><span>Online claim review does not release an item. The staff role is a local demonstration.</span></div>`;}
function insightsPage(){const a=analytics(state.data.reports,state.data.claims,{since:state.analyticsSince,until:state.analyticsUntil});const max=Math.max(1,...a.byCategory.map(x=>x.count));const latest=state.data.reports.filter(r=>r.kind==='found'&&policyFor(r.category,r.value,r.itemType).review&&!r.approved).length;const custodyBacklog=state.data.custody.filter(c=>c.status!=='released').length;return `${pageTitle('THE CAMPUS PICTURE','Insights & trends','Counts come from this browser’s reports. Unique linked duplicates are excluded.',`<label class="date-filter">From <input id="date-from" type="date" value="${esc(state.analyticsSince||'')}"></label><label class="date-filter">To <input id="date-to" type="date" value="${esc(state.analyticsUntil||'')}"></label>`)}<div class="stats-grid">${statCard('Lost reports',a.lost,'Unique reports in range','⌕')}${statCard('Found reports',a.found,'Unique reports in range','＋')}${statCard('Confirmed recoveries',a.recovered,'Handover completed','✓')}${statCard('Unresolved',a.unresolved,'Still open','◷')}${statCard('Pending claims',a.pendingClaims,'Need a next step','◇')}${statCard('Recovery rate',`${a.recoveryRate}%`,'Recovered ÷ unique reports','↗')}</div><div class="insights-grid"><section class="panel chart-panel"><div class="panel-heading"><div><div class="eyebrow">REPORT MIX</div><h3>Reports by category</h3></div><span class="chart-unit">Unique reports</span></div>${a.byCategory.length?`<div class="bar-chart">${a.byCategory.map(x=>`<div class="bar-row"><span>${esc(x.category)}</span><div class="bar-track"><i style="width:${Math.max(5,x.count/max*100)}%"></i></div><b>${x.count}</b></div>`).join('')}</div>`:empty('▥','No category data yet','Reports will appear here after submission.')}</section><section class="panel chart-panel"><div class="panel-heading"><div><div class="eyebrow">WHERE REPORTS HAPPEN</div><h3>Frequent locations</h3></div><button class="text-button" data-page="map">Open map →</button></div>${a.byLocation.length?a.byLocation.slice(0,6).map((x,i)=>`<div class="location-stat"><span class="rank-position">${String(i+1).padStart(2,'0')}</span><b>${esc(x.location.name)}</b><span>${x.lost} lost · ${x.found} found</span><strong>${x.count}</strong></div>`).join(''):empty('⌖','No location activity','Location patterns are calculated from submitted reports.')}</section></div><div class="insights-grid trend-grid">${trendPanel('Weekly reports',a.weekly)}${trendPanel('Monthly reports',a.monthly)}</div><div class="stats-footnote"><span>Recovery rate definition</span><p>Confirmed handovers ÷ unique lost and found reports in the selected period. Claims, possible matches, and custody acceptance do not count as recovery.</p></div><div class="backlog-row">${statCard('Average time to recovery',a.averageDays!==null?`${a.averageDays} days`:'—','Report to confirmed handover','◷')}${statCard('Sensitive review backlog',latest,'Found reports awaiting staff review','▤')}${statCard('Official custody backlog',custodyBacklog,'Custody records not released','▣')}</div>`;}
function trendPanel(title,series){const max=Math.max(1,...series.map(x=>x.count));return `<section class="panel chart-panel trend-panel"><div class="panel-heading"><div><div class="eyebrow">REPORTS OVER TIME</div><h3>${title}</h3></div><span class="chart-unit">Number of reports</span></div>${series.length?`<div class="trend-bars">${series.slice(-8).map(x=>`<div class="trend-col"><b>${x.count}</b><i style="height:${Math.max(4,x.count/max*100)}%"></i><small>${esc(x.period)}</small></div>`).join('')}</div><div class="axis-caption">Period · count of unique non-duplicate reports</div>`:empty('▥','No time-series data','Reports will appear here when submitted.')}</section>`;}
function activityPage(){const mine=state.data.reports.filter(r=>r.owner==='demo').sort((a,b)=>b.createdAt.localeCompare(a.createdAt));const myClaims=state.data.claims.filter(c=>c.owner==='demo').sort((a,b)=>b.createdAt.localeCompare(a.createdAt));const notices=[...state.data.notifications].sort((a,b)=>b.createdAt.localeCompare(a.createdAt));return `${pageTitle('YOUR RECORDS','My activity','Your reports, claims, notifications, and next steps.')}<div class="activity-tabs"><button class="active" data-activity-tab="reports">My reports <span>${mine.length}</span></button><button data-activity-tab="claims">Claims <span>${myClaims.length}</span></button><button data-activity-tab="notifications">Notifications <span>${notices.filter(n=>!n.read).length}</span></button></div><div id="activity-content">${activityContent('reports',mine,myClaims,notices)}</div>`;}
function activityContent(tab,mine,myClaims,notices){if(tab==='claims')return myClaims.length?`<div class="case-list">${myClaims.map(c=>{const r=state.data.reports.find(x=>x.id===c.reportId);return `<article class="case-card"><div class="case-id">${esc(c.id.slice(-8).toUpperCase())}</div><div class="case-main"><div class="case-title"><b>${esc(r?.itemType||'Found item')}</b>${statusPill(c.status)}</div><p>Submitted ${ago(c.createdAt)} · ${esc(c.reportId)}</p>${c.status==='More information required'?`<button class="text-button" data-add-evidence="${c.id}">Add information →</button>`:''}</div>${r?button('View item','btn-secondary',`data-open-report="${r.id}"`):''}</article>`;}).join('')}</div>`:empty('◇','No claims yet','When you find a published found report that may be yours, open it to submit a private claim.');if(tab==='notifications')return notices.length?`<div class="notification-list">${notices.map(n=>`<button class="notification ${n.read?'':'unread'}" data-notification="${n.id}" ${n.reportId?`data-open-report="${n.reportId}"`:''}><span class="notification-mark">${n.read?'○':'●'}</span><span><b>${esc(n.message)}</b><small>${ago(n.createdAt)} · ${n.reportId?esc(n.reportId):'Campus FindIt'}</small></span></button>`).join('')}</div>`:empty('♧','You’re all caught up','Notifications from real report and claim activity will show here.');return mine.length?`<div class="report-list">${mine.map(r=>`<div class="activity-report">${cardReport(r)}<div class="activity-actions">${r.status!=='recovered'?`<button class="text-button" data-withdraw="${r.id}">Withdraw</button>`:''}<button class="text-button" data-report-detail="${r.id}">Details →</button></div></div>`).join('')}</div>`:empty('◷','No reports yet','Your lost and found reports will appear here.',button('Create a report','btn-primary','data-page="report"'));}
function adminPage(){if(state.role!=='staff')return `${pageTitle('DEMO STAFF WORKSPACE','Authorized staff','Switch to the staff demo role to review cases and manage custody.')}<div class="panel access-panel"><div class="access-icon">⚙</div><h2>Staff workspace</h2><p>This area demonstrates staff-only workflows. The role switcher simulates a role locally and is not real authentication.</p>${button('Switch to demo staff','btn-primary','id="role-switch-inline"')}</div>`;const pending=state.data.reports.filter(r=>r.kind==='found'&&!r.approved&&r.status!=='withdrawn');const allClaims=state.data.claims.filter(c=>!['Recovered','Rejected'].includes(c.status));const dup=state.data.reports.flatMap(r=>duplicateCandidates(r,state.data.reports).map(d=>({r,d}))).filter((x,i,a)=>a.findIndex(y=>`${y.r.id}|${y.d.id}`===`${x.r.id}|${x.d.id}`)<0);return `${pageTitle('STAFF DEMO ROLE','Admin & review','Review reports, resolve claims, and record custody and handover.',`<button class="btn-secondary" id="export-data">Export local data</button> <label class="btn-secondary import-label">Import data<input id="import-data" type="file" accept="application/json" hidden></label>`)}<div class="admin-summary">${statCard('Reports to review',pending.length,'Found item submissions','◷')}${statCard('Claims to review',allClaims.length,'Open claims','◇')}${statCard('Possible duplicates',dup.length,'Review before linking','↔')}${statCard('Audit events',state.data.audit.length,'Recorded actions','▤')}</div><div class="section-head"><div><div class="eyebrow">PUBLICATION REVIEW</div><h2>Found reports</h2></div></div>${pending.length?`<div class="admin-list">${pending.map(r=>`<article class="admin-row"><div class="admin-item"><span class="report-thumb found">＋</span><div><b>${esc(r.itemType)} · ${esc(r.category)}</b><small>${esc(loc(r.locationId)?.name)} · ${dateLabel(r.date)} · ${policyFor(r.category,r.value,r.itemType).label}</small><small>Public description: ${esc(r.publicDescription||r.description)}</small></div></div><div class="admin-actions"><button class="btn-secondary" data-open-report="${r.id}">Review details</button><button class="btn-primary" data-approve-report="${r.id}">Approve & publish</button><button class="text-button danger" data-reject-report="${r.id}">Reject</button></div></article>`).join('')}</div>`:empty('✓','Review queue is clear','New found reports appear here until staff review them.')}<div class="section-head"><div><div class="eyebrow">CLAIM REVIEW</div><h2>Ownership claims</h2></div></div>${allClaims.length?`<div class="case-list">${allClaims.map(c=>{const r=state.data.reports.find(x=>x.id===c.reportId);return `<article class="case-card"><div class="case-id">${esc(c.id.slice(-8).toUpperCase())}</div><div class="case-main"><div class="case-title"><b>${esc(r?.itemType||'Missing report')}</b>${statusPill(c.status)}</div><p>${esc(c.reportId)} · submitted ${ago(c.createdAt)}</p><div class="claim-evidence"><b>Claimant explanation</b><span>${esc(c.explanation)}</span><b>Private ownership details</b><span>${esc(c.evidence||'No additional evidence provided')}</span></div>${c.extraEvidence?`<small>Follow-up: ${esc(c.extraEvidence)}</small>`:''}</div><div class="admin-actions">${button('Request more info','btn-secondary',`data-claim-action="${c.id}" data-status="More information required"`)}${button('Approve for in-person check','btn-primary',`data-claim-action="${c.id}" data-status="Approved for in-person verification"`)}${button('Reject claim','btn-quiet danger',`data-claim-action="${c.id}" data-status="Rejected"`)}</div></article>`;}).join('')}</div>`:empty('◇','No claims to review','Submitted claims appear here for staff review.') }<div class="section-head"><div><div class="eyebrow">OFFICIAL CUSTODY</div><h2>Custody & handover</h2></div></div>${custodyPanel() }<div class="section-head"><div><div class="eyebrow">QUALITY REVIEW</div><h2>Possible duplicate reports</h2></div></div>${dup.length?dup.slice(0,8).map(x=>`<div class="duplicate-row"><span>${esc(x.r.id)} · ${esc(x.r.itemType)}</span><span>may overlap with</span><span>${esc(x.d.id)} · ${esc(x.d.itemType)}</span><button class="btn-secondary" data-link-duplicate="${x.r.id}" data-duplicate-target="${x.d.id}">Link duplicate</button></div>`).join(''):empty('↔','No likely duplicates','Possible duplicates are identified by category, time, and location.')}<div class="section-head"><div><div class="eyebrow">CONFIGURATION</div><h2>Campus landmarks</h2></div></div><div class="panel landmark-config">${LOCATIONS.map(l=>`<span><b>${esc(l.name)}</b><small>${esc(l.type)} · ${l.x}, ${l.y}</small></span>`).join('')}</div><div class="reset-panel"><div><b>Local data tools</b><small>Export a versioned JSON backup or reset this browser’s records.</small></div><button class="btn-quiet danger" id="reset-data">Reset all local data</button></div>`;}
function custodyPanel(){const eligible=state.data.claims.filter(c=>c.status==='Approved for in-person verification'||c.status==='Handover pending'||c.status==='Recovered');if(!eligible.length)return empty('▣','No handovers ready','A staff-approved claim will appear here for custody and in-person verification.');return `<div class="custody-list">${eligible.map(c=>{const r=state.data.reports.find(x=>x.id===c.reportId);let record=state.data.custody.find(x=>x.claimId===c.id);return `<article class="custody-card"><div class="custody-heading"><div><b>${esc(r?.itemType||'Found item')} · ${esc(r?.id)}</b><small>Claim ${esc(c.id)} · ${policyFor(r?.category,r?.value,r?.itemType).label}</small></div>${statusPill(c.status)}</div>${record?`<p>Custody ref <b>${esc(record.id)}</b> · received ${dateLabel(record.receivedAt.slice(0,10))} · custodian ${esc(record.custodian)}</p>`:''}<div class="checklist"><label><input type="checkbox" data-check="identity" data-claim="${c.id}" ${record?.identityChecked?'checked':''}> In-person identity and ownership check completed</label><label><input type="checkbox" data-check="item" data-claim="${c.id}" ${record?.itemChecked?'checked':''}> Item condition and custody reference confirmed</label><label><input type="checkbox" data-check="ack" data-claim="${c.id}" ${record?.recipientAcknowledged?'checked':''}> Recipient acknowledgement recorded</label></div>${!record?button('Accept into official custody','btn-secondary',`data-create-custody="${c.id}"`):''}${record&&c.status!=='Recovered'?button('Complete handover & mark recovered','btn-primary',`data-handover="${c.id}"`):''}${c.status==='Recovered'?`<div class="recovered-note">✓ Handover completed and recorded</div>`:''}</article>`;}).join('')}</div>`;}
function render(){const page={home:homePage,map:mapPage,find:findPage,report:reportPage,recovery:recoveryPage,insights:insightsPage,activity:activityPage,admin:adminPage}[state.page]||homePage;app.innerHTML=layout(page());bind();bindMapPan();scaleMap();}
function openModal(title,body,actions=''){modal.innerHTML=`<div class="modal-head"><div><div class="eyebrow">CAMPUS FINDIT</div><h2 id="modal-title">${title}</h2></div><button class="icon-button" data-close-modal aria-label="Close">×</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}`;modal.querySelector('[data-close-modal]').addEventListener('click',closeModal);modal.showModal();}
function closeModal(){modal.close();}
async function showReport(id){const r=state.data.reports.find(x=>x.id===id);if(!r){toast('That report could not be found.');return;}state.selectedReport=id;const p=publicReport(r);const restricted=state.role==='staff';const matches=r.kind==='lost'?state.data.reports.filter(f=>f.kind==='found'&&f.approved).map(f=>({f,...matchScore(r,f)})).filter(x=>x.score>=35).sort((a,b)=>b.score-a.score):[];let body=`<div class="detail-layout">${p?.image?`<img class="detail-image" src="${p.image}" alt="Item photo">`:''}<div class="detail-tags"><span class="kind-tag ${r.kind}">${r.kind.toUpperCase()}</span>${statusPill(r.status)}</div><h3>${esc(p?.itemType||r.itemType||r.category)}</h3><p>${esc(p?.description||r.publicDescription||r.description)}</p><div class="detail-meta"><span>⌖ ${esc(p?.locationName||loc(r.locationId)?.name||'Campus')}</span><span>◷ ${dateLabel(r.date)}</span><span>Report ${esc(r.id)}</span></div>${r.kind==='found'&&r.approved&&r.status!=='recovered'?`<div class="privacy-callout"><span>◈</span><div><b>Found item privacy</b><p>Unique identifying details are kept private until staff review and in-person verification.</p></div></div>`:''}${restricted?`<div class="restricted-box"><b>Staff restricted view · demo only</b><p>Private clue: ${esc(r.privateClue||'No private clue supplied')}</p><p>Additional location detail: ${esc(r.locationDetail||'Not provided')}</p><p>Handling: ${esc(r.handling||'Not specified')} · Value: ${esc(r.value||'Not specified')}</p></div>`:''}${r.kind==='found'&&r.approved&&state.role==='student'&&isOpen(r)?`<form id="claim-form" data-report="${r.id}"><h4>Think this could be yours?</h4><label>Why do you believe this is your item? <span>*</span><textarea name="explanation" rows="3" maxlength="500" required placeholder="Share enough context for staff to review."></textarea></label><label>Private distinguishing details <small>shown to staff only</small><textarea name="evidence" rows="2" maxlength="500" placeholder="Add a detail that can help verify ownership"></textarea></label><button class="btn-primary" type="submit">Submit ownership claim →</button></form>`:''}${matches.length?`<div class="possible-matches"><h4>Possible found reports</h4>${matches.map(m=>`<button data-open-report="${m.f.id}"><b>${esc(m.f.itemType)}</b><small>${m.score} points · ${m.factors.join(' · ')}</small>→</button>`).join('')}</div>`:''}</div>`;openModal(`${r.kind==='lost'?'Lost':'Found'} item`,body);modal.querySelector('.detail-layout')?.addEventListener('submit',async e=>{if(e.target.id!=='claim-form')return;e.preventDefault();if(state.data.claims.some(c=>c.owner==='demo'&&c.reportId===r.id&&!['Rejected'].includes(c.status))){toast('You already have a claim for this item.');return;}const fd=new FormData(e.target),c={id:uid('claim'),reportId:r.id,owner:'demo',explanation:fd.get('explanation'),evidence:fd.get('evidence'),status:'Submitted',createdAt:now(),updatedAt:now()};await put('claims',c);await notify('A new ownership claim was submitted for review.',r.id);await audit('Claim submitted',c.id);closeModal();await refresh();toast('Claim submitted for staff review.');});modal.querySelectorAll('[data-open-report]').forEach(b=>b.addEventListener('click',()=>showReport(b.dataset.openReport)));}
function bind(){app.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));app.querySelectorAll('[data-report-kind]').forEach(b=>b.addEventListener('click',()=>{state.kind=b.dataset.reportKind;if(state.page!=='report')go('report');else render();}));app.querySelectorAll('[data-open-report]').forEach(b=>b.addEventListener('click',()=>showReport(b.dataset.openReport)));document.querySelectorAll('[data-close-modal]').forEach(b=>b.addEventListener('click',closeModal));
  const switchRole=()=>{state.role=state.role==='staff'?'student':'staff';localStorage.setItem('cfi-role',state.role);render();toast(`Now viewing as demo ${state.role}.`);};app.querySelector('#role-switch')?.addEventListener('click',switchRole);app.querySelector('#role-switch-top')?.addEventListener('click',switchRole);app.querySelector('#role-switch-inline')?.addEventListener('click',switchRole);
  app.querySelector('#bell')?.addEventListener('click',()=>{go('activity');setTimeout(()=>app.querySelector('[data-activity-tab="notifications"]')?.click(),0);});
  app.querySelector('#report-form')?.addEventListener('submit',submitReport);
  app.querySelector('#search-query')?.addEventListener('input',e=>{state.filters.query=e.target.value;const pos=e.target.selectionStart;render();const input=app.querySelector('#search-query');input?.focus();input?.setSelectionRange(pos,pos);});
  app.querySelectorAll('.filters-panel select').forEach(sel=>sel.addEventListener('change',()=>{state.filters[sel.name]=sel.value;render();}));app.querySelector('#clear-filters')?.addEventListener('click',()=>{state.filters={kind:'all',category:'all',location:'all',status:'all',query:''};render();});
  app.querySelectorAll('[data-map-mode]').forEach(b=>b.addEventListener('click',()=>{state.mapMode=b.dataset.mapMode;render();}));app.querySelectorAll('[data-map-layer]').forEach(b=>b.addEventListener('click',()=>{state.mapLayer=b.dataset.mapLayer;render();}));app.querySelector('.map-extra-filters select[name=category]')?.addEventListener('change',e=>{state.mapCategory=e.target.value;render();});app.querySelector('.map-extra-filters select[name=status]')?.addEventListener('change',e=>{state.mapStatus=e.target.value;render();});app.querySelector('#map-date-from')?.addEventListener('change',e=>{state.mapSince=e.target.value||null;render();});app.querySelector('#map-search')?.addEventListener('input',e=>{state.mapQuery=e.target.value;const pos=e.target.selectionStart;render();const i=app.querySelector('#map-search');i?.focus();i?.setSelectionRange(pos,pos);});app.querySelectorAll('[data-map-location]').forEach(b=>b.addEventListener('click',()=>{state.mapSelected=b.dataset.mapLocation;render();}));app.querySelector('#clear-location')?.addEventListener('click',()=>{state.mapSelected=null;render();});app.querySelector('#zoom-in')?.addEventListener('click',()=>{state.zoom=Math.min(1.5,state.zoom+.1);scaleMap();});app.querySelector('#zoom-out')?.addEventListener('click',()=>{state.zoom=Math.max(.75,state.zoom-.1);scaleMap();});app.querySelector('#map-reset')?.addEventListener('click',()=>{state.zoom=1;state.panX=0;state.panY=0;state.mapSelected=null;state.mapQuery='';render();});app.querySelectorAll('[data-map-report]').forEach(b=>b.addEventListener('click',()=>{state.kind='lost';go('report');app.querySelector('[name="locationId"]').value=b.dataset.mapReport;}));app.querySelectorAll('[data-filter-location]').forEach(b=>b.addEventListener('click',()=>{state.filters.location=b.dataset.filterLocation;go('find');}));
  app.querySelectorAll('[data-activity-tab]').forEach(b=>b.addEventListener('click',()=>{app.querySelectorAll('[data-activity-tab]').forEach(x=>x.classList.toggle('active',x===b));app.querySelector('#activity-content').innerHTML=activityContent(b.dataset.activityTab,state.data.reports.filter(r=>r.owner==='demo'),state.data.claims.filter(c=>c.owner==='demo'),state.data.notifications);bindActivity();}));bindActivity();
  app.querySelectorAll('[data-approve-report]').forEach(b=>b.addEventListener('click',()=>setReportReview(b.dataset.approveReport,true)));app.querySelectorAll('[data-reject-report]').forEach(b=>b.addEventListener('click',()=>setReportReview(b.dataset.rejectReport,false)));app.querySelectorAll('[data-claim-action]').forEach(b=>b.addEventListener('click',()=>changeClaim(b.dataset.claimAction,b.dataset.status)));app.querySelectorAll('[data-create-custody]').forEach(b=>b.addEventListener('click',()=>createCustody(b.dataset.createCustody)));app.querySelectorAll('[data-check]').forEach(b=>b.addEventListener('change',()=>updateChecklist(b.dataset.claim,b.dataset.check,b.checked)));app.querySelectorAll('[data-handover]').forEach(b=>b.addEventListener('click',()=>completeHandover(b.dataset.handover)));app.querySelectorAll('[data-link-duplicate]').forEach(b=>b.addEventListener('click',()=>linkDuplicate(b.dataset.linkDuplicate,b.dataset.duplicateTarget)));app.querySelector('#export-data')?.addEventListener('click',exportBackup);app.querySelector('#import-data')?.addEventListener('change',importBackup);app.querySelector('#reset-data')?.addEventListener('click',resetData);
  app.querySelector('#date-from')?.addEventListener('change',updateInsightsDate);app.querySelector('#date-to')?.addEventListener('change',updateInsightsDate);app.querySelector('#hotspot-range')?.addEventListener('change',()=>{const days=Number(app.querySelector('#hotspot-range').value);state.hotspotSince=days?new Date(Date.now()-days*86400000).toISOString():null;render();});app.querySelector('#hotspot-min')?.addEventListener('change',()=>render());
  app.querySelectorAll('[data-withdraw]').forEach(b=>b.addEventListener('click',()=>withdrawReport(b.dataset.withdraw)));app.querySelectorAll('[data-report-detail]').forEach(b=>b.addEventListener('click',()=>showReport(b.dataset.reportDetail)));app.querySelectorAll('[data-add-evidence]').forEach(b=>b.addEventListener('click',()=>addEvidence(b.dataset.addEvidence)));app.querySelectorAll('[data-notification]').forEach(b=>b.addEventListener('click',()=>markRead(b.dataset.notification)));
}
function scaleMap(){const svg=app.querySelector('#campus-map');if(svg)svg.style.transform=`translate(${state.panX}px, ${state.panY}px) scale(${state.zoom})`;const n=app.querySelector('.map-controls span');if(n)n.textContent=`${Math.round(state.zoom*100)}%`;}
function bindMapPan(){const viewport=app.querySelector('.map-viewport');if(!viewport)return;let drag=null;viewport.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,moved:false};viewport.setPointerCapture(e.pointerId);});viewport.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>3)drag.moved=true;state.panX+=dx;state.panY+=dy;drag.x=e.clientX;drag.y=e.clientY;scaleMap();});viewport.addEventListener('pointerup',()=>{if(drag?.moved)state.mapDragged=true;drag=null;});viewport.addEventListener('pointercancel',()=>{drag=null;});viewport.addEventListener('click',e=>{if(!state.mapDragged)return;e.stopImmediatePropagation();state.mapDragged=false;},true);}
async function submitReport(e){e.preventDefault();const form=e.currentTarget,fd=new FormData(form);if(!form.reportValidity())return;let image=null;const file=fd.get('image');if(file?.size){if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Choose a JPG, PNG, or WebP image.');return;}if(file.size>3*1024*1024){toast('Image must be 3 MB or smaller.');return;}image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});}
  const kind=fd.get('kind'),category=fd.get('category'),location=loc(fd.get('locationId')),policy=policyFor(category,fd.get('value'),fd.get('itemType'));const r={id:uid(kind),kind,category,itemType:fd.get('itemType').trim(),brand:fd.get('brand').trim(),color:fd.get('color').trim(),date:fd.get('date'),time:fd.get('time'),locationId:location.id,locationName:location.name,locationDetail:fd.get('locationDetail').trim(),description:fd.get('description').trim(),publicDescription:kind==='found'&&policy.level===3?'A sensitive item has been handed to authorized campus staff.':fd.get('description').trim(),privateClue:fd.get('privateClue')?.trim()||'',value:fd.get('value')||'Less expensive',handling:fd.get('handling')||'',image,status:kind==='found'?'under review':'open',approved:false,owner:'demo',createdAt:now(),updatedAt:now(),policyLevel:policy.level};const dup=duplicateCandidates(r,state.data.reports);if(dup.length&&!confirm(`This looks similar to ${dup[0].id} near ${location.name}. Submit anyway for staff review?`))return;try{await saveReport(r);}catch(err){toast(`Could not save report: ${err.message}`);return;}state.data.reports.push(r);openModal('Report submitted',`<div class="success-mark">✓</div><p>Your ${kind} report has been saved in this browser.</p><div class="reference-box"><small>REPORT REFERENCE</small><b>${esc(r.id)}</b></div><p>${kind==='found'?'A staff reviewer will check this report before it is published.':'Your report is available in My activity and may be compared with approved found reports.'}</p>`,button('Go to My activity','btn-primary','id="success-activity"'));modal.querySelector('#success-activity')?.addEventListener('click',()=>{closeModal();go('activity');});}
async function setReportReview(id,approved){const r=state.data.reports.find(x=>x.id===id);if(!r||state.role!=='staff')return toast('Staff role required.');r.approved=approved;r.status=approved?'active':'rejected';r.updatedAt=now();await put('reports',r);await audit(approved?'Found report approved':'Found report rejected',id);if(approved){const candidates=state.data.reports.filter(l=>l.kind==='lost').map(l=>({l,...matchScore(l,r)})).filter(x=>x.score>=45);for(const m of candidates)await notify(`A possible match is available for your ${m.l.id}.`,m.l.id);}await refresh();toast(approved?'Report approved and published.':'Report rejected.');}
async function changeClaim(id,status){if(state.role!=='staff')return toast('Staff role required.');const c=state.data.claims.find(x=>x.id===id);if(!c)return;c.status=status;c.updatedAt=now();await put('claims',c);await audit(`Claim status changed to ${status}`,id);await notify(`Your claim is now ${status.toLowerCase()}.`,c.reportId);await refresh();toast('Claim updated.');}
async function createCustody(claimId){if(state.role!=='staff')return toast('Staff role required.');const c=state.data.claims.find(x=>x.id===claimId);if(!c||c.status!=='Approved for in-person verification')return toast('Claim must be approved for in-person verification first.');if(!state.data.custody.some(x=>x.claimId===claimId)){const record={id:uid('custody'),claimId,reportId:c.reportId,custodian:'Demo campus staff',status:'in custody',receivedAt:now(),identityChecked:false,itemChecked:false,recipientAcknowledged:false};await put('custody',record);await audit('Item accepted into official custody',record.id);await notify('An item has entered official custody.',c.reportId);}c.status='Handover pending';c.updatedAt=now();await put('claims',c);await refresh();toast('Custody record created.');}
async function updateChecklist(claimId,key,value){const record=state.data.custody.find(x=>x.claimId===claimId);if(!record||state.role!=='staff')return;const k={identity:'identityChecked',item:'itemChecked',ack:'recipientAcknowledged'}[key];record[k]=value;record.updatedAt=now();await put('custody',record);await audit(`Handover checklist ${value?'checked':'unchecked'}: ${key}`,record.id);}
async function completeHandover(claimId){if(state.role!=='staff')return toast('Staff role required.');const record=state.data.custody.find(x=>x.claimId===claimId),claim=state.data.claims.find(x=>x.id===claimId),r=state.data.reports.find(x=>x.id===claim?.reportId);if(!record||!claim||!r)return toast('Custody or claim record is missing.');if(!record.identityChecked||!record.itemChecked||!record.recipientAcknowledged)return toast('Complete all three handover checks first.');if(!confirm('Confirm the in-person handover? This marks the report recovered.'))return;record.status='released';record.handoverAt=now();record.releasedBy='Demo campus staff';record.updatedAt=now();claim.status='Recovered';claim.updatedAt=now();r.status='recovered';r.updatedAt=now();await put('custody',record);await put('claims',claim);await put('reports',r);await audit('Physical handover completed',r.id,'Recipient acknowledgement recorded');await notify('Recovery completed after staff recorded the handover.',r.id);await refresh();toast('Handover recorded. Report marked recovered.');}
async function linkDuplicate(id,target){if(state.role!=='staff')return toast('Staff role required.');const r=state.data.reports.find(x=>x.id===id);if(!r||!confirm(`Mark ${id} as a duplicate of ${target}?`))return;r.duplicateOf=target;r.updatedAt=now();await put('reports',r);await audit('Reports linked as duplicates',id,target);await refresh();toast('Duplicate link recorded.');}
async function addEvidence(id){const c=state.data.claims.find(x=>x.id===id);if(!c)return;openModal('Add information',`<form id="evidence-form"><label>Additional ownership information<textarea name="text" rows="4" required maxlength="500" placeholder="Add a detail requested by staff"></textarea></label><button class="btn-primary" type="submit">Send to staff</button></form>`);modal.querySelector('#evidence-form').addEventListener('submit',async e=>{e.preventDefault();c.extraEvidence=new FormData(e.currentTarget).get('text');c.status='Under review';c.updatedAt=now();await put('claims',c);await audit('Claim evidence added',id);closeModal();await refresh();toast('Information sent for review.');});}
async function markRead(id){const n=state.data.notifications.find(x=>x.id===id);if(n&&!n.read){n.read=true;await put('notifications',n);await refresh();}}
async function withdrawReport(id){const r=state.data.reports.find(x=>x.id===id);if(!r||!confirm('Withdraw this report? Existing claims and custody history will remain.'))return;r.status='withdrawn';r.updatedAt=now();await put('reports',r);await audit('Report withdrawn',id);await refresh();toast('Report withdrawn.');}
function updateInsightsDate(){state.analyticsSince=app.querySelector('#date-from').value||null;state.analyticsUntil=app.querySelector('#date-to').value||null;render();}
async function exportBackup(){const data=await exportData(),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`campus-findit-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);toast('Local data export downloaded.');}
async function importBackup(e){const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());await importData(data);await audit('Data imported','local');await refresh();toast('Data imported.');}catch(err){toast(err.message||'Import failed.');}}
async function resetData(){if(!confirm('Permanently clear all Campus FindIt records from this browser?'))return;await clearAll();await refresh();toast('Local records cleared.');}
function bindActivity(){app.querySelectorAll('[data-withdraw]').forEach(b=>b.addEventListener('click',()=>withdrawReport(b.dataset.withdraw)));app.querySelectorAll('[data-report-detail]').forEach(b=>b.addEventListener('click',()=>showReport(b.dataset.reportDetail)));app.querySelectorAll('[data-add-evidence]').forEach(b=>b.addEventListener('click',()=>addEvidence(b.dataset.addEvidence)));app.querySelectorAll('[data-notification]').forEach(b=>b.addEventListener('click',()=>markRead(b.dataset.notification)));app.querySelectorAll('[data-open-report]').forEach(b=>b.addEventListener('click',()=>showReport(b.dataset.openReport)));}
function init(){const hash=location.hash.slice(1);if(NAV.some(x=>x[0]===hash))state.page=hash;refresh().catch(e=>{app.innerHTML=`<div class="storage-error"><h1>Could not open local storage</h1><p>${esc(e.message)}</p><button onclick="location.reload()">Retry</button></div>`;});}
modal.addEventListener('click',e=>{if(e.target===modal)closeModal();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal.open)closeModal();});
init();
